function esc(x){return String(x==null?"":x).replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]})}function fmt(s,o){return s.replace(/\{(\w+)\}/g,function(_,k){return esc(o[k])})}
function money(n){return new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:0}).format(n)}function toast(s){$("#toast").textContent=s;setTimeout(function(){$("#toast").textContent=""},2400)}
